import React, { useState, useEffect } from 'react';
import { 
    Box, 
    TextField, 
    Button, 
    
    Typography,
    alpha,
    CircularProgress,
    
   
    MenuItem,
    Select
} from '@mui/material';
import { 
    Person as PersonIcon,
    Email as EmailIcon,
    Home as AddressIcon,
    Wc as GenderIcon,
    Work as JobIcon,
} from '@mui/icons-material';
import BaseModal from '../BaseModal';
import FileUpload from '../FileUpload';

const EditUserModal = ({ 
    open, 
    onClose, 
    onSubmit, 
    userData = null, 
    loading = false 
}) => {
   

    const [formData, setFormData] = useState({
        name: '',
        email: '',
        profile_image: '',
        address: '',
        gender: 'male',
        mentor_gender: 'female',
        job_type: 'office'
    });

    useEffect(() => {
        if (open && userData) {
            setFormData({
                name: userData.name || '',
                email: userData.email || '',
                profile_image: userData.profile?.profile_image || userData.profile_image || '',
                address: userData.profile?.address || '',
                gender: userData.profile?.gender || 'male',
                mentor_gender: userData.profile?.mentor_gender || 'female',
                job_type: userData.profile?.job_type || 'office'
            });
        }
    }, [open, userData]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ 
            ...prev, 
            [name]: value 
        }));
    };

    const handleUploadSuccess = (url) => {
        setFormData(prev => ({ ...prev, profile_image: url }));
    };

    const handleSubmit = (e) => {
        if (e) e.preventDefault();
        onSubmit(formData);
    };

    const GENDER_OPTIONS = ['male', 'female', 'other'];
    const MENTOR_GENDER_OPTIONS = ['male', 'female', 'both'];
    const JOB_TYPE_OPTIONS = ['office', 'remote', 'hybrid'];

    const actions = (
        <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, width: '100%', flexDirection: { xs: 'column', sm: 'row' } }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    color: 'text.secondary', 
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleSubmit}
                disabled={loading || !formData.name.trim() || !formData.email.trim()}
                sx={{ 
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    color: '#000',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(0, 0, 0, 0.5)'
                    }
                }}
            >
                {loading ? (
                    <CircularProgress size={24} color="inherit" />
                ) : (
                    'Save Changes'
                )}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={userData ? `Edit Profile: ${userData.name}` : 'Edit Profile'}
            maxWidth="sm"
            actions={actions}
        >
            <Box 
                component="form" 
                onSubmit={handleSubmit} 
                sx={{ 
                    pt: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 2.5,
                    width: '100%',
                }}
            >
                {/* Profile Image Upload */}
                <Box sx={{ display: 'flex', justifyContent: 'center', mb: 1 }}>
                    <FileUpload
                        folderName="user_profiles"
                        maxFiles={1}
                        existingImageUrl={formData.profile_image}
                        onUploadSuccess={handleUploadSuccess}
                        onRemove={() => setFormData(prev => ({ ...prev, profile_image: '' }))}
                        shape="circle"
                        helperText="Profile Photo (max. 5MB)"
                    />
                </Box>

                {/* Name */}
                <Box>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <PersonIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Full Name
                    </Typography>
                    <TextField
                        fullWidth
                        name="name"
                        value={formData.name}
                        onChange={handleChange}
                        required
                        placeholder="Enter full name..."
                        variant="outlined"
                        autoComplete="off"
                    />
                </Box>

                {/* Email */}
                <Box>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <EmailIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Email Address
                    </Typography>
                    <TextField
                        fullWidth
                        name="email"
                        type="email"
                        value={formData.email}
                        onChange={handleChange}
                        required
                        placeholder="Enter email address..."
                        variant="outlined"
                        autoComplete="off"
                    />
                </Box>

                {/* Address */}
                <Box>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <AddressIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Address
                    </Typography>
                    <TextField
                        fullWidth
                        name="address"
                        value={formData.address}
                        onChange=   {handleChange}
                        placeholder="City, Country..."
                        variant="outlined"
                        autoComplete="off"
                    />
                </Box>

                {/* Genders Row */}
                <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                    <Box sx={{ flex: 1, minWidth: '140px' }}>
                        <Typography 
                            variant="caption" 
                            sx={{ 
                                color: 'text.secondary', 
                                fontWeight: 700, 
                                mb: 1, 
                                display: 'flex', 
                                alignItems: 'center',
                                gap: 1,
                                textTransform: 'uppercase',
                                letterSpacing: '0.05em'
                            }}
                        >
                            <GenderIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                            Gender
                        </Typography>
                        <Select
                            fullWidth
                            name="gender"
                            value={formData.gender}
                            onChange={handleChange}
                            variant="outlined"
                            sx={{
                                '& .MuiSelect-select': { py: 1.5 }
                            }}
                        >
                            {GENDER_OPTIONS.map(opt => (
                                <MenuItem key={opt} value={opt}>{opt.charAt(0).toUpperCase() + opt.slice(1)}</MenuItem>
                            ))}
                        </Select>
                    </Box>

                    <Box sx={{ flex: 1, minWidth: '140px' }}>
                        <Typography 
                            variant="caption" 
                            sx={{ 
                                color: 'text.secondary', 
                                fontWeight: 700, 
                                mb: 1, 
                                display: 'flex', 
                                alignItems: 'center',
                                gap: 1,
                                textTransform: 'uppercase',
                                letterSpacing: '0.05em'
                            }}
                        >
                            <GenderIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                            Mentor Preference
                        </Typography>
                        <Select
                            fullWidth
                            name="mentor_gender"
                            value={formData.mentor_gender}
                            onChange={handleChange}
                            variant="outlined"
                            sx={{
                                '& .MuiSelect-select': { py: 1.5 }
                            }}
                        >
                            {MENTOR_GENDER_OPTIONS.map(opt => (
                                <MenuItem key={opt} value={opt}>{opt.charAt(0).toUpperCase() + opt.slice(1)}</MenuItem>
                            ))}
                        </Select>
                    </Box>
                </Box>

                {/* Job Type */}
                <Box>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <JobIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Job Type
                    </Typography>
                    <Select
                        fullWidth
                        name="job_type"
                        value={formData.job_type}
                        onChange={handleChange}
                        variant="outlined"
                        sx={{
                            '& .MuiSelect-select': { py: 1.5 }
                        }}
                    >
                        {JOB_TYPE_OPTIONS.map(opt => (
                            <MenuItem key={opt} value={opt}>{opt.charAt(0).toUpperCase() + opt.slice(1)}</MenuItem>
                        ))}
                    </Select>
                </Box>
            </Box>
        </BaseModal>
    );
};

export default EditUserModal;
