import React, { useState, useEffect } from 'react';
import {
  Box,
  TextField,
  Button,
  Typography,
  alpha,
  CircularProgress,
  IconButton,
  InputAdornment,
  Tooltip,
} from '@mui/material';
import {
  Lock as LockIcon,
  LockReset as LockResetIcon,
  Visibility,
  VisibilityOff,
  Autorenew as RefreshIcon,
} from '@mui/icons-material';
import BaseModal from '../BaseModal';
import ConfirmationModal from '../ConfirmationModal';
import PasswordStrengthBar from '../PasswordStrengthBar';
import { generatePassword } from '../../utils/passwordGenerator';

const fieldLabelSx = {
  color: 'text.secondary',
  fontWeight: 700,
  mb: 1,
  display: 'flex',
  alignItems: 'center',
  gap: 1,
  textTransform: 'uppercase',
  letterSpacing: '0.05em',
};

const iconButtonSx = {
  width: 32,
  height: 32,
  p: 0.5,
  flexShrink: 0,
};

const refreshButtonSx = {
  ...iconButtonSx,
  color: '#4CC66E',
  bgcolor: 'rgba(76, 198, 110, 0.15)',
  '&:hover': {
    bgcolor: 'rgba(76, 198, 110, 0.28)',
  },
};

const validatePassword = (password) => {
  if (!password) return 'Password is required';
  if (password.length < 8) return 'Password must be at least 8 characters';
  if (!/[A-Z]/.test(password)) return 'Password must contain at least one uppercase letter';
  if (!/[a-z]/.test(password)) return 'Password must contain at least one lowercase letter';
  if (!/[0-9]/.test(password)) return 'Password must contain at least one number';
  if (!/[^A-Za-z0-9]/.test(password)) return 'Password must contain at least one special character';
  return '';
};

const ResetUserPasswordModal = ({
  open,
  onClose,
  onSubmit,
  userData = null,
  loading = false,
}) => {
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [errors, setErrors] = useState({});
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  useEffect(() => {
    if (open) {
      setNewPassword('');
      setConfirmPassword('');
      setShowPassword(false);
      setShowConfirmPassword(false);
      setErrors({});
      setShowConfirmModal(false);
    } else {
      setShowConfirmModal(false);
    }
  }, [open]);

  const handleGeneratePassword = () => {
    const password = generatePassword();
    setNewPassword(password);
    setConfirmPassword(password);
    setShowPassword(true);
    setShowConfirmPassword(true);
    setErrors({});
  };

  const passwordAdornment = (
    <InputAdornment position="end">
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
        <Tooltip title="Generate random password">
          <IconButton
            size="small"
            onClick={handleGeneratePassword}
            sx={refreshButtonSx}
            aria-label="Generate password"
          >
            <RefreshIcon sx={{ fontSize: 18 }} />
          </IconButton>
        </Tooltip>
        <IconButton
          size="small"
          onClick={() => setShowPassword((prev) => !prev)}
          sx={iconButtonSx}
          aria-label={showPassword ? 'Hide password' : 'Show password'}
        >
          {showPassword ? <VisibilityOff sx={{ fontSize: 18 }} /> : <Visibility sx={{ fontSize: 18 }} />}
        </IconButton>
      </Box>
    </InputAdornment>
  );

  const confirmAdornment = (
    <InputAdornment position="end">
      <IconButton
        size="small"
        onClick={() => setShowConfirmPassword((prev) => !prev)}
        sx={iconButtonSx}
        aria-label={showConfirmPassword ? 'Hide confirm password' : 'Show confirm password'}
      >
        {showConfirmPassword ? <VisibilityOff sx={{ fontSize: 18 }} /> : <Visibility sx={{ fontSize: 18 }} />}
      </IconButton>
    </InputAdornment>
  );

  const handleSubmit = (e) => {
    if (e) e.preventDefault();

    const nextErrors = {};
    const passwordError = validatePassword(newPassword);
    if (passwordError) nextErrors.newPassword = passwordError;
    if (!confirmPassword) {
      nextErrors.confirmPassword = 'Please confirm the password';
    } else if (newPassword !== confirmPassword) {
      nextErrors.confirmPassword = 'Passwords do not match';
    }

    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      return;
    }

    setShowConfirmModal(true);
  };

  const handleConfirmReset = () => {
    onSubmit({ newPassword });
  };

  const handleClose = () => {
    if (loading) return;
    setShowConfirmModal(false);
    onClose();
  };

  const handleConfirmClose = () => {
    if (loading) return;
    setShowConfirmModal(false);
  };

  const confirmMessage = userData?.name ? (
    <>
      Are you sure you want to change the password for{' '}
      <Box component="span" sx={{ color: '#FFFFFF', fontWeight: 700 }}>
        {userData.name}
      </Box>
      {userData.email ? (
        <>
          {' '}
          (
          <Box component="span" sx={{ color: '#4CC66E', fontWeight: 600 }}>
            {userData.email}
          </Box>
          )
        </>
      ) : null}
      ? The new password will take effect immediately and the user will need it to sign in.
    </>
  ) : (
    'Are you sure you want to change this user\'s password? The new password will take effect immediately.'
  );

  const actions = (
    <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, width: '100%', flexDirection: { xs: 'column', sm: 'row' } }}>
      <Button
        fullWidth
        variant="outlined"
        onClick={handleClose}
        disabled={loading}
        sx={{
          color: 'text.secondary',
          boxShadow: 'none',
          borderColor: 'rgba(255, 255, 255, 0.1)',
          '&:hover': {
            borderColor: 'text.secondary',
            bgcolor: 'rgba(255, 255, 255, 0.05)',
          },
        }}
      >
        Cancel
      </Button>
      <Button
        fullWidth
        variant="contained"
        onClick={handleSubmit}
        disabled={loading || !newPassword || !confirmPassword}
        sx={{
          fontWeight: 700,
          bgcolor: '#4CC66E',
          color: '#000',
          '&:hover': { bgcolor: '#3EB05D' },
          '&.Mui-disabled': {
            bgcolor: alpha('#4CC66E', 0.5),
            color: 'rgba(0, 0, 0, 0.5)',
          },
        }}
      >
        {loading ? <CircularProgress size={24} color="inherit" /> : 'Change Password'}
      </Button>
    </Box>
  );

  return (
    <>
      <BaseModal
        open={open && !showConfirmModal}
        onClose={handleClose}
        title={userData ? `Change Password: ${userData.name}` : 'Change Password'}
        maxWidth="sm"
        actions={actions}
      >
      <Box
        component="form"
        onSubmit={handleSubmit}
        sx={{
          pt: 1,
          display: 'flex',
          flexDirection: 'column',
          gap: 2.5,
          width: '100%',
        }}
      >
        <Typography
          variant="body2"
          sx={{ color: 'text.secondary', lineHeight: 1.6 }}
        >
          Set a new password for{' '}
          <Box component="span" sx={{ color: '#FFFFFF', fontWeight: 600 }}>
            {userData?.email || 'this user'}
          </Box>
          . The user will be able to sign in immediately with the new password.
        </Typography>

        <Box>
          <Typography variant="caption" sx={fieldLabelSx}>
            <LockIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
            New Password
          </Typography>
          <TextField
            fullWidth
            name="newPassword"
            type={showPassword ? 'text' : 'password'}
            value={newPassword}
            onChange={(e) => {
              setNewPassword(e.target.value);
              if (errors.newPassword) setErrors((prev) => ({ ...prev, newPassword: '' }));
            }}
            required
            placeholder="Enter new password..."
            variant="outlined"
            autoComplete="new-password"
            error={Boolean(errors.newPassword)}
            helperText={errors.newPassword || 'Click refresh to generate a secure password'}
            InputProps={{
              endAdornment: passwordAdornment,
            }}
          />
          {newPassword ? <PasswordStrengthBar password={newPassword} /> : null}
        </Box>

        <Box>
          <Typography variant="caption" sx={fieldLabelSx}>
            <LockIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
            Confirm Password
          </Typography>
          <TextField
            fullWidth
            name="confirmPassword"
            type={showConfirmPassword ? 'text' : 'password'}
            value={confirmPassword}
            onChange={(e) => {
              setConfirmPassword(e.target.value);
              if (errors.confirmPassword) setErrors((prev) => ({ ...prev, confirmPassword: '' }));
            }}
            required
            placeholder="Confirm new password..."
            variant="outlined"
            autoComplete="new-password"
            error={Boolean(errors.confirmPassword)}
            helperText={errors.confirmPassword}
            InputProps={{
              endAdornment: confirmAdornment,
            }}
          />
        </Box>
      </Box>
      </BaseModal>

      <ConfirmationModal
        open={open && showConfirmModal}
        onClose={handleConfirmClose}
        onConfirm={handleConfirmReset}
        title="Confirm Password Change"
        message={confirmMessage}
        confirmText="Yes, Proceed"
        confirmColor="warning"
        icon={LockResetIcon}
        loading={loading}
      />
    </>
  );
};

export default ResetUserPasswordModal;
