import React, { useState, useEffect } from 'react';
import { 
    Box, 
    TextField, 
    Button, 
    useTheme,
    Typography,
    alpha,
    CircularProgress
} from '@mui/material';
import { 
    Title as TitleIcon, 
    Message as MessageIcon,
    Notifications as NotificationIcon 
} from '@mui/icons-material';
import BaseModal from '../BaseModal';

const UserNotificationModal = ({ 
    open, 
    onClose, 
    onSubmit, 
    userData = null, 
    loading = false 
}) => {
    const theme = useTheme();

    const [formData, setFormData] = useState({
        title: '',
        message: '',
    });

    useEffect(() => {
        if (open) {
            setFormData({
                title: '',
                message: '',
            });
        }
    }, [open]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ 
            ...prev, 
            [name]: value 
        }));
    };

    const handleSubmit = (e) => {
        if (e) e.preventDefault();
        onSubmit(formData);
    };

    const actions = (
        <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, width: '100%', flexDirection: { xs: 'column', sm: 'row' } }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    color: 'text.secondary', 
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleSubmit}
                disabled={loading || !formData.title.trim() || !formData.message.trim()}
                sx={{ 
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(255, 255, 255, 0.5)'
                    }
                }}
            >
                {loading ? (
                    <CircularProgress size={24} color="inherit" />
                ) : (
                    'Send Notification'
                )}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={userData ? `Send Notification to ${userData.name}` : 'Send Notification'}
            maxWidth="sm"
            actions={actions}
        >
            <Box 
                component="form" 
                onSubmit={handleSubmit} 
                sx={{ 
                    pt: 2,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 2.5,
                    width: '100%',
                }}
            >
                <Box>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <TitleIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Notification Title
                    </Typography>
                    <TextField
                        fullWidth
                        name="title"
                        value={formData.title}
                        onChange={handleChange}
                        required
                        placeholder="Enter notification title..."
                        variant="outlined"
                        autoComplete="off"
                    />
                </Box>

                <Box>
                    <Typography 
                        variant="caption" 
                        sx={{ 
                            color: 'text.secondary', 
                            fontWeight: 700, 
                            mb: 1, 
                            display: 'flex', 
                            alignItems: 'center',
                            gap: 1,
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        <MessageIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Message Content
                    </Typography>
                    <TextField
                        fullWidth
                        multiline
                        rows={4}
                        name="message"
                        value={formData.message}
                        onChange={handleChange}
                        required
                        placeholder="Type your message here..."
                        variant="outlined"
                    />
                </Box>
            </Box>
        </BaseModal>
    );
};

export default UserNotificationModal;
