const CHARSETS = {
    uppercase: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    lowercase: 'abcdefghijklmnopqrstuvwxyz',
    numbers: '0123456789',
    symbols: '@#$',
};

const getRandomIndex = (max) => {
    const array = new Uint32Array(1);
    crypto.getRandomValues(array);
    return array[0] % max;
};

export const DEFAULT_PASSWORD_LENGTH = 8;

export const generatePassword = ({
    length = DEFAULT_PASSWORD_LENGTH,
    uppercase = true,
    lowercase = true,
    numbers = true,
    symbols = true,
} = {}) => {
    const activeSets = [];

    if (uppercase) activeSets.push(CHARSETS.uppercase);
    if (lowercase) activeSets.push(CHARSETS.lowercase);
    if (numbers) activeSets.push(CHARSETS.numbers);
    if (symbols) activeSets.push(CHARSETS.symbols);

    if (activeSets.length === 0) return '';

    const allChars = activeSets.join('');
    const passwordChars = [];

    activeSets.forEach((set) => {
        passwordChars.push(set[getRandomIndex(set.length)]);
    });

    while (passwordChars.length < length) {
        passwordChars.push(allChars[getRandomIndex(allChars.length)]);
    }

    for (let i = passwordChars.length - 1; i > 0; i -= 1) {
        const j = getRandomIndex(i + 1);
        [passwordChars[i], passwordChars[j]] = [passwordChars[j], passwordChars[i]];
    }

    return passwordChars.join('');
};
